package mz.bam.seeky.android;
import android.app.*;import android.content.res.Configuration;import android.graphics.*;import android.os.*;import android.text.*;import android.view.*;import java.io.*;import java.util.concurrent.TimeUnit;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,qualifiers="w720dp-h360dp-land-mdpi",application=Application.class,shadows={PageTurnTest.EpubWeb.class}) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ReaderText5152Test {
 PageTurnTest fixture;ReaderActivity a;
 @Before public void setup()throws Exception{fixture=new PageTurnTest();fixture.setup();a=fixture.a;a.getSharedPreferences("seeky",0).edit().putBoolean("reader_ruler",true).apply();a.extras.ruler.refresh();layout(720,360);}
 @After public void close(){fixture.close();}
 void layout(int w,int h)throws Exception{a.getWindow().setLayout(w,h);for(int n=0;n<4;n++){fixture.drain();a.root.measure(View.MeasureSpec.makeMeasureSpec(w,1073741824),View.MeasureSpec.makeMeasureSpec(h,1073741824));a.root.layout(0,0,w,h);a.root.getViewTreeObserver().dispatchOnGlobalLayout();shadowOf(Looper.getMainLooper()).idle();}}
 void drag(float x,float y,float dx,float dy)throws Exception{int[] at=new int[2],root=new int[2];a.bookScroll.getLocationOnScreen(at);a.root.getLocationOnScreen(root);long t=SystemClock.uptimeMillis();for(int i=0;i<=6;i++){MotionEvent e=MotionEvent.obtain(t,t+i*30,i==0?MotionEvent.ACTION_DOWN:i==6?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE,at[0]-root[0]+x+dx*i/6,at[1]-root[1]+y+dy*i/6,0);a.root.dispatchTouchEvent(e);e.recycle();shadowOf(Looper.getMainLooper()).idleFor(30,TimeUnit.MILLISECONDS);}for(int n=0;n<32;n++){shadowOf(Looper.getMainLooper()).idleFor(16,TimeUnit.MILLISECONDS);a.bookScroll.computeScroll();}}
 @Test public void landscapeTextScrollsVerticallyThroughVisibleRuler()throws Exception{assertTrue(a.body.getHeight()>=260);assertEquals(View.VISIBLE,a.extras.ruler.getVisibility());drag(300,200,0,-130);assertTrue("text scroll="+a.bookScroll.getScrollY(),a.bookScroll.getScrollY()>60);assertEquals(0,a.chapter);}
 @Test public void landscapeHorizontalTurnAndSelectionRemainIndependent()throws Exception{drag(580,100,-250,0);int moved=a.bookScroll.getScrollY();assertTrue(moved>0);assertEquals(0,a.chapter);Selection.setSelection((Spannable)a.bookText.getText(),0,10);drag(500,100,-200,0);assertEquals(0,a.chapter);assertTrue(Math.abs(moved-a.bookScroll.getScrollY())<=a.bookText.getLineHeight());assertTrue(a.bookText.isTextSelectable());assertTrue(a.bookText.getSelectionStart()>=0);}
 @Test public void rotationRecreatesReaderAtSavedChapterAndScroll()throws Exception{a.bookScroll.scrollTo(0,650);int saved=a.bookScroll.getScrollY();Configuration portrait=new Configuration(a.getResources().getConfiguration());portrait.orientation=Configuration.ORIENTATION_PORTRAIT;portrait.screenWidthDp=360;portrait.screenHeightDp=720;fixture.controller.configurationChange(portrait);a=fixture.controller.get();fixture.a=a;layout(360,720);assertFalse(a.chrome.compact);assertEquals(0,a.chapter);assertEquals("stored after="+a.getSharedPreferences("seeky",0).getInt("reader_scroll_"+a.uri+":0",-1)+" pending="+a.tools.pendingOffset+" original="+a.original.active+" text="+a.bookText.getHeight()+" ready="+a.readingReady(),saved,a.bookScroll.getScrollY());assertEquals(View.VISIBLE,a.chrome.toolStrip.getChildAt(5).getVisibility());}
}
